// Twelve player-facing fields retain all nineteen underlying question banks and history.
const LEARNING_FIELDS=[
['maths','Mathematics',['maths'],'Fractions, measurement, data & patterns'],
['english','English & Literacy',['english'],'Reading, spelling, grammar & writing'],
['science','Science & Living Things',['science','biology','chemistry'],'Biology, chemistry, energy, Earth & space'],
['history','History',['history'],'Australia, First Nations histories & the past'],
['geography','Geography',['geography'],'Maps, countries, environments & connections'],
['civics','Society, Citizenship & Money',['civics','economics','social'],'Democracy, economics & current social issues'],
['digital','Technology & Design',['digital','design'],'Coding, online safety, making & engineering'],
['arts','Arts & Music',['arts','music'],'Visual art, drama, rhythm & pitch'],
['sports','Sport, Health & Wellbeing',['sports','health'],'Sport, teamwork, nutrition & healthy choices'],
['languages','Languages & Cultures',['languages'],'Words, communication & different cultures'],
['general','General Knowledge',['general'],'Everyday wonders, inventions & discoveries'],
['logic','Logic and Puzzles',['logic'],'Patterns, deduction & IQ-style puzzles']
].map(([id,name,banks,desc])=>({...SUBJECTS.find(s=>s.id===id),id,name,banks,desc}));
let questionClock=null,roundTimed=false,roundElapsed=0,roundKeys=[],activeInvite=null,completedChallenge=null,friendDraft=false,practiceDraft=false;
const safeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cleanName=v=>String(v||'').replace(/[\u0000-\u001f\u007f]/g,'').trim().slice(0,20);
function fieldBanks(ids){return [...new Set(ids.flatMap(id=>LEARNING_FIELDS.find(f=>f.id===id)?.banks||[]))]}
function fieldIdsFor(banks){return LEARNING_FIELDS.filter(f=>f.banks.some(id=>banks.includes(id))).map(f=>f.id)}
function selectedFields(){const saved=Array.isArray(profile.learningFields)?profile.learningFields:fieldIdsFor(profile.battleTopics||['maths']);return saved.filter(id=>LEARNING_FIELDS.some(f=>f.id===id))}
topicShortcuts=function(){return `<section class="field-shortcuts"><b>13 FIELDS · ALWAYS 10 QUESTIONS</b><div><button data-action="mixed">✓ Choose multiple fields</button><button data-action="random-round">✦ Random mix</button><button data-action="friend-round">⚑ Share a score challenge</button></div></section>`};
topicCatalogue=function(){return `<div class="section-title"><div><h2>13 learning fields. One big adventure.</h2><p>Tap any field to open the selection screen, then add as many fields as you like.</p></div><span class="count">${QUESTION_COUNT} QUESTIONS & VARIATIONS</span></div><div class="subjects">${LEARNING_FIELDS.map(f=>`<button class="subject" data-subject="${f.id}" style="--accent:${f.colour}"><div class="subject-top"><div class="subject-icon">${f.icon}</div><span class="zone">${f.banks.reduce((n,id)=>n+(typeof eligibleBankLength==='function'?eligibleBankLength(id):BANK[id].length),0)} QUESTIONS</span></div><h3>${f.name}</h3><p>${f.desc}</p><div class="subject-foot"><span>CHOOSE THIS + MORE FIELDS</span><b>+</b></div></button>`).join('')}</div>`};
topicPickerGroups=function(selected){return `<div class="picker-group-grid">${LEARNING_FIELDS.map(f=>`<button data-topic="${f.id}" aria-pressed="${selected.includes(f.id)}" class="topic-choice ${selected.includes(f.id)?'selected':''}"><span style="color:${f.colour}">${f.icon}</span><b>${f.name}</b><i>${selected.includes(f.id)?'✓':'+'}</i></button>`).join('')}</div>`};
chooseBattleTopics=function(initial){practiceDraft=false;if(typeof liveDraft!=='undefined')liveDraft=false;activeInvite=null;completedChallenge=null;topicDraft=initial?[initial]:selectedFields();if(!topicDraft.length)topicDraft=['maths'];drawTopicPicker(false)};
zoneChoice=function(id){friendDraft=false;chooseBattleTopics(LEARNING_FIELDS.find(f=>f.id===id)?.id||fieldIdsFor([id])[0])};
drawTopicPicker=function(keepScroll=true){const scroll=keepScroll?(document.querySelector('.topic-picker')?.scrollTop||0):0;openModal(`${topModal(friendDraft?'FRIEND CHALLENGE · ROUND SETUP':'BUILD YOUR BATTLE LOADOUT')}<h2 id="modal-title" class="modal-title">Choose one or more fields.</h2><p class="sub">Tap fields to tick or untick them. Any number of selected fields still gives <b>10 random questions total</b>.</p><div class="round-settings"><label>Player nickname <input id="round-name" maxlength="20" autocomplete="off" placeholder="e.g. CosmicCollie" value="${safeText(profile.playerName)}"></label><label>Question timer <select id="round-timer"><option value="off" ${!profile.questionTimed?'selected':''}>No time limit</option><option value="on" ${profile.questionTimed?'selected':''}>1 minute per question</option></select></label></div><p class="notice">${friendDraft?'Finish this round, then share your challenge link. Your friend gets the same 10 questions and timer.':'Each correct answer adds one battle heart. Timed-out questions earn no heart and automatically advance.'}</p><div class="topic-quick"><button class="text-btn" data-topic-choice="all">Select all 13</button><button class="text-btn" data-topic-choice="random">Random mix</button><button class="text-btn" data-topic-choice="clear">Clear</button></div><div class="topic-picker">${topicPickerGroups(topicDraft)}</div><div class="topic-summary"><p><b>${topicDraft.length} fields selected · 10 questions total</b><span>${profile.questionTimed?'60 seconds each':'No question time limit'} · ${selectedMode().name} battle</span></p><button class="primary" data-action="start-warmup" ${topicDraft.length?'':'disabled'}>Start 10 questions →</button></div>`);const list=document.querySelector('.topic-picker');if(list)list.scrollTop=scroll};
function saveRoundInputs(){const name=document.querySelector('#round-name'),timer=document.querySelector('#round-timer');if(name)profile.playerName=cleanName(name.value);if(timer)profile.questionTimed=timer.value==='on';save()}
function launchConfiguredRound(){saveRoundInputs();if(!topicDraft.length)return;if(friendDraft&&!profile.playerName){toast('Choose a player nickname to create your friend challenge.');document.querySelector('#round-name')?.focus();return}profile.learningFields=[...topicDraft];profile.battleTopics=fieldBanks(topicDraft);save();roundTimed=!!profile.questionTimed;roundElapsed=0;completedChallenge=null;if(typeof liveDraft!=='undefined'&&liveDraft)createLiveRoom();else if(practiceDraft)startPractice(profile.battleTopics);else startArena('mixed')}
const preparationBase=buildPreparation;
buildPreparation=function(subject){const q=preparationBase(subject);if(activeInvite){q.deck=activeInvite.keys.map(key=>{const[id,n]=key.split(':');return{id,index:+n,q:BANK[id][+n]}});q.sections=[...new Set(q.deck.map(item=>item.id))];roundTimed=activeInvite.timed}else roundTimed=!!profile.questionTimed;roundElapsed=0;roundKeys=q.deck.map(questionKey);q.timed=roundTimed;return q};
const arenaStartBase=startArena;
startArena=function(subject){clearQuestionClock();arenaStartBase(subject);const intro=document.querySelector('#modal-content .modal-actions');intro?.insertAdjacentHTML('beforebegin',`<p class="round-timer-note">${roundTimed?'⏱ 60 seconds per question. Unanswered questions automatically advance.':'∞ No question time limit. Think it through at your pace.'}</p>`);const content=document.querySelector('#modal-content');if(content)content.innerHTML=content.innerHTML.replace('Questions stay untimed.','Your question timer follows the setting above.');};
function clearQuestionClock(){if(questionClock!==null)clearInterval(questionClock);questionClock=null}
function secondsLeft(deadline,now=Date.now()){return Math.max(0,Math.ceil((deadline-now)/1000))}
function tickQuestionClock(){if(!quiz||quiz.answered){clearQuestionClock();return}const remaining=secondsLeft(quiz.deadline),timer=document.querySelector('#question-countdown');if(timer){timer.textContent=`⏱ ${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} left`;timer.classList.toggle('urgent',remaining<=10)}if(!remaining){answer(-1);toast('Time is up — moving to the next question.');nextQuestion()}}
const askBase=ask;
ask=function(){clearQuestionClock();const same=quiz?.clockPosition===quiz?.pos&&Number.isFinite(quiz?.startedAt);askBase();if(quiz.mode==='arena')return;if(!same){quiz.clockPosition=quiz.pos;quiz.startedAt=Date.now();quiz.deadline=quiz.timed?Date.now()+60000:null}const hint=document.querySelector('#modal-content .hint');if(hint)hint.textContent=quiz.mode==='preparation'?`♥ ${quiz.right} extra hearts earned · 10 questions total · ${quiz.timed?'60 seconds per question':'No time limit'}`:(quiz.timed?'60 seconds per question. A timeout automatically advances.':'No time limit. Think it through.');document.querySelector('.modal-top')?.insertAdjacentHTML('afterend',`<div id="question-countdown" class="question-countdown" role="timer" aria-label="Question time remaining">${quiz.timed?'⏱ 1:00 left':'∞ No time limit'}</div>`);if(quiz.timed){tickQuestionClock();if(quiz&&!quiz.answered)questionClock=setInterval(tickQuestionClock,250)}};
const answerBase=answer;
answer=function(n){if(!quiz||quiz.answered)return;clearQuestionClock();if(quiz.mode==='preparation')roundElapsed+=Math.min(quiz.timed?60000:Infinity,Math.max(0,Date.now()-(quiz.startedAt||Date.now())));answerBase(n)};
const recordPreparationBase=recordPreparationAnswer;
recordPreparationAnswer=function(right){recordPreparationBase(right);const hint=document.querySelector('#modal-content .hint');if(hint)hint.textContent=`♥ ${quiz.right} extra hearts earned · 10 questions total · ${quiz.timed?'60 seconds per question':'No time limit'}`};
const navigateBase=navigate;
navigate=function(p){clearQuestionClock();navigateBase(p)};
function encodeChallenge(data){return btoa(unescape(encodeURIComponent(JSON.stringify(data))))}
function decodeChallenge(encoded){try{if(!encoded||encoded.length>5000)return null;const d=JSON.parse(decodeURIComponent(escape(atob(encoded))));if(d.v!==1||!Array.isArray(d.keys)||d.keys.length!==10||new Set(d.keys).size!==10||!d.keys.every(k=>typeof k==='string'&&/^[a-z]+:\d+$/.test(k)&&BANK[k.split(':')[0]]?.[+k.split(':')[1]])||typeof d.timed!=='boolean'||!Number.isInteger(d.right)||d.right<0||d.right>10||!Number.isFinite(d.ms)||d.ms<0||d.ms>600000||typeof d.name!=='string')return null;return{v:1,keys:d.keys,timed:d.timed,right:d.right,ms:d.ms,name:cleanName(d.name)||'Your friend'}}catch{return null}}
function challengeURL(data){const url=new URL(window.location.href);url.search='';url.hash='challenge='+encodeChallenge(data);return url.href}
function challengeComparison(mine,target){if(mine.right!==target.right)return mine.right>target.right?'You beat the challenge!':'Your friend takes this round.';if(mine.timed&&mine.ms!==target.ms)return mine.ms<target.ms?'You win the time tie-break!':'Your friend wins the time tie-break.';return 'A shared victory — it’s a tie!'}
function challengeResultHTML(result){return `<section class="friend-result"><span class="eyebrow">10-QUESTION FRIEND CHALLENGE</span><h3>${activeInvite?challengeComparison(result,activeInvite):'Your challenge is ready to share.'}</h3><div class="friend-scores"><div><b>${safeText(result.name)}</b><strong>${result.right}/10</strong><small>${result.timed?(result.ms/1000).toFixed(1)+'s answer time':'No time limit'}</small></div>${activeInvite?`<div><b>${safeText(activeInvite.name)}</b><strong>${activeInvite.right}/10</strong><small>${activeInvite.timed?(activeInvite.ms/1000).toFixed(1)+'s answer time':'No time limit'}</small></div>`:''}</div><p>Compare correct answers${result.timed?', then answer time to break a tie':''}. Share your result for the next challenge.</p><button class="secondary" data-action="share-challenge">Copy challenge link ↗</button><label class="share-label">Challenge link <input id="challenge-link" readonly value="${safeText(challengeURL(result))}"></label><small>Play in turns on separate devices. Scores travel in the link; there is no live multiplayer or online leaderboard.</small></section>`}
const preparationResultsBase=preparationResults;
preparationResults=function(){clearQuestionClock();const result={v:1,keys:[...roundKeys],timed:!!quiz.timed,right:quiz.right,ms:Math.min(600000,Math.round(roundElapsed)),name:cleanName(profile.playerName)||'Quest Player'};completedChallenge=result;preparationResultsBase();if(friendDraft||activeInvite)document.querySelector('.loadout-results')?.insertAdjacentHTML('afterbegin',challengeResultHTML(result));else document.querySelector('.loadout-results')?.insertAdjacentHTML('beforeend','<button class="secondary" data-action="share-challenge">Challenge a friend with this round ↗</button>')};
function incomingChallenge(){if(!window.questionLibraryReady)return;const hash=window.location.hash;if(!hash.startsWith('#challenge='))return;const data=decodeChallenge(hash.slice(11));if(!data){toast('This challenge link is invalid or uses unavailable questions. Create a new round.');return}activeInvite=data;friendDraft=true;openModal(`${topModal('A FRIEND CHALLENGED YOU')}<h2 id="modal-title">Can you beat ${safeText(data.name)}?</h2><p class="feedback">Same 10 questions · ${data.timed?'1 minute per question':'No time limit'} · Your friend scored <b>${data.right}/10</b>${data.timed?' in '+(data.ms/1000).toFixed(1)+' seconds of answer time':''}.</p><label class="nickname-label">Your player nickname <input id="invite-name" maxlength="20" placeholder="Choose a nickname" value="${safeText(profile.playerName)}"></label><p class="notice">Play in turns and compare learning scores. No account needed. Use a nickname rather than your full name.</p><button class="primary" data-action="accept-challenge">Accept 10-question challenge →</button>`)}
const homeBase=home;
home=function(){const html=homeBase();return html.replace('<section class="field-shortcuts">',`<section class="player-card player-identity"><label for="player-name"><span class="identity-mark" aria-hidden="true">✦</span><span>Player nickname<small>For friend challenges</small></span></label><input id="player-name" maxlength="20" placeholder="Choose your nickname" value="${safeText(profile.playerName)}"><button class="secondary" data-action="save-name">Save name</button></section><section class="field-shortcuts">`)};
document.addEventListener('change',e=>{if(e.target.id==='round-name'||e.target.id==='round-timer'){saveRoundInputs();const summary=document.querySelector('.topic-summary p span');if(summary)summary.textContent=(profile.questionTimed?'60 seconds each':'No question time limit')+(practiceDraft?' · Practice without combat':' · '+selectedMode().name+' battle')}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.action;
if(b.dataset.topic||b.dataset.topicChoice)saveRoundInputs();
if(b.dataset.topicChoice){e.stopImmediatePropagation();topicDraft=b.dataset.topicChoice==='all'||b.dataset.topicChoice==='random'?LEARNING_FIELDS.map(f=>f.id):[];drawTopicPicker();if(b.dataset.topicChoice==='random')toast('Random mix selected: 10 questions drawn from all 13 fields.');return}
if(action==='start-warmup'){e.stopImmediatePropagation();launchConfiguredRound();return}
if(action==='mixed')friendDraft=false;
if(['leave','done','confirm-reset'].includes(action)){clearQuestionClock();activeInvite=null;friendDraft=false}
if(action==='random-round'){e.stopImmediatePropagation();friendDraft=false;chooseBattleTopics();topicDraft=LEARNING_FIELDS.map(f=>f.id);drawTopicPicker(false)}
if(action==='friend-round'){e.stopImmediatePropagation();chooseBattleTopics();friendDraft=true;drawTopicPicker(false)}
if(action==='save-name'){const name=cleanName(document.querySelector('#player-name')?.value);if(!name){toast('Enter a nickname first.');return}profile.playerName=name;save();page.innerHTML=home();toast(profile.playerName?'Player nickname saved.':'Nickname cleared.')}
if(action==='accept-challenge'){const name=cleanName(document.querySelector('#invite-name')?.value);if(!name){toast('Enter your player nickname first.');return}profile.playerName=name;save();startArena('mixed')}
if(action==='share-challenge'&&completedChallenge){const url=challengeURL(completedChallenge);if(!document.querySelector('#challenge-link'))document.querySelector('.loadout-results')?.insertAdjacentHTML('beforeend',challengeResultHTML(completedChallenge));try{await navigator.clipboard.writeText(url);toast('Challenge link copied. Share it with your friend!')}catch{const input=document.querySelector('#challenge-link');input?.focus();input?.select();toast('Select and copy the challenge link below.')}}
},true);
const drawPickerBase=drawTopicPicker;
drawTopicPicker=function(keep=true){drawPickerBase(keep);if(practiceDraft){const content=document.querySelector('#modal-content');content.innerHTML=content.innerHTML.replace('BUILD YOUR BATTLE LOADOUT','PRACTICE ROUND SETUP').replace('Each correct answer adds one battle heart. Timed-out questions earn no heart and automatically advance.','Practice without combat. Read explanations and build your knowledge. Timed-out questions automatically advance.').replace(' · '+selectedMode().name+' battle',' · Practice without combat')}};
practiceChoice=function(){friendDraft=false;chooseBattleTopics();practiceDraft=true;drawTopicPicker(false)};
startPractice=function(subject,review=false){clearQuestionClock();closeModal();const ids=Array.isArray(subject)?subject:subject==='mixed'?fieldBanks(selectedFields()):fieldBanks([subject]);const d=review?shuffle(profile.missed.map(key=>{const[id,index]=key.split(':');return{id,index:+index,q:BANK[id][index]}})):buildQuestionDeck(ids.length?ids:['maths']);quiz={mode:'practice',deck:d.slice(0,review?d.length:10),pos:0,right:0,subject,timed:!!profile.questionTimed};ask()};
const closeRequestBase=closeRequest;
closeRequest=function(){if(quiz?.timed&&!quiz.answered){toast('The question timer keeps running. Answer now or use Leave round.');return}closeRequestBase()};
const askTimedBase=ask;
ask=function(){askTimedBase();if(quiz?.timed&&!quiz.answered)document.querySelector('#modal-content .hint')?.insertAdjacentHTML('afterend','<button class="text-btn timed-leave" data-action="leave">Leave round</button>')};
const resultFieldsBase=preparationResults;
preparationResults=function(){const scores=quiz.sectionScores;resultFieldsBase();const rows=LEARNING_FIELDS.map(f=>({f,total:f.banks.reduce((n,id)=>n+(scores[id]?.total||0),0),correct:f.banks.reduce((n,id)=>n+(scores[id]?.correct||0),0)})).filter(s=>s.total);const list=document.querySelector('.section-results');if(list)list.innerHTML=rows.map(s=>`<div><span>${s.f.name}</span><b>${s.correct} / ${s.total}</b></div>`).join('')};
const progressBase=progress;
progress=function(){return progressBase().replace(/<div class="progress-row"[\s\S]*?(?=<button class="primary" data-action="review")/,LEARNING_FIELDS.map(f=>{const total=f.banks.reduce((n,id)=>n+(profile.subjects[id]?.total||0),0),correct=f.banks.reduce((n,id)=>n+(profile.subjects[id]?.correct||0),0);return `<div class="progress-row" style="--accent:${f.colour}"><b>${f.icon} ${f.name}</b><div class="track"><span style="width:${total?correct/total*100:0}%"></span></div><small>${correct}/${total}</small></div>`}).join(''))};
window.addEventListener('hashchange',incomingChallenge);
navigate('home');incomingChallenge();





